def bold(text: str) -> str:
    if backend == "latex":
        return r"\textbf{" + text + "}"
    elif backend == "html":
        return f"<strong>{text}</strong>"
    elif backend == "markdown":
        return f"**{text}**"
    raise ValueError(f"Unsupported backend: {backend}")
